import re

def doc_contradictions(doc_text, behavior):
    hits = []
    for key, val in behavior.items():
        m = re.search(r"-\s*" + re.escape(key) + r":\s*(\d+)", doc_text)
        if m and int(m.group(1)) != val:
            hits.append(f"{key}: 文档说 {m.group(1)} 实际 {val}")
    return hits

